local a=require"system.filesystem"local b=require"system.util"local c=assert(b.argparse({a=false,s=false,k=false,h=false,x=false,H=false,L=false},...))if#c==0 then c[1]="."end;local d=0;local function e(f)if c.h then if f>=1000000000000 then return("%.3gT"):format(f/1000000000000)elseif f>=1000000000 then return("%.3gG"):format(f/1000000000)elseif f>=1000000 then return("%.3gM"):format(f/1000000)elseif f>=1000 then return("%.3gK"):format(f/1000)else return("%.3g "):format(f)end elseif c.k then return math.ceil(f/1024)else return math.ceil(f/512)end end;local function g(h,i,j)local k,l=a.stat(h,not(j and c.H or c.L))if k then if i==true then i=k.mountpoint end;if i and i~=k.mountpoint then return 0 end;if k.type=="directory"then local m=0;for n,o in ipairs(a.list(h))do m=m+g(a.combine(h,o),i)end;if not c.s then print(e(m),h)end;return m else if c.a and not c.s then print(e(k.size),h)end;return k.size end else io.stderr:write("du: could not stat "..h..": "..(l or"").."\n")d=1;return 0 end end;for n,o in ipairs(c)do local m=g(o,c.x,true)if c.s then print(e(m),o)end end;return d
